mapper.select:
select blockedcardlistinfo.CID, BExpire, BDescription, BCreateTime, sys_user_login.UserName, user.UNAME, card.Status from blockedcardlistinfo, card, sys_user_login, user where card.CID = blockedcardlistinfo.CID and sys_user_login.UID = card.UID and sys_user_login.UID = user.UID
and card.CID = #{cid}
and UserName = #{username}
